git_mirror_dir="${proxy_dir%/}/git-mirror"
github_credential_file="$git_mirror_dir/github.credential"
export DEPENDENCY_GITHUB_CREDENTIAL_FILE="$github_credential_file"

prepare_git_credentials() {
  mkdir -p "$git_mirror_dir"
  credential=
  if command -v git >/dev/null 2>&1; then
    credential=$(printf 'protocol=https\nhost=github.com\n\n' | \
      GIT_TERMINAL_PROMPT=0 git credential fill 2>/dev/null || true)
  fi
  username=$(printf '%s\n' "$credential" | sed -n 's/^username=//p' | head -n 1)
  password=$(printf '%s\n' "$credential" | sed -n 's/^password=//p' | head -n 1)
  umask 077
  if [ -n "$password" ]; then
    printf '%s\n%s\n' "$username" "$password" >"$github_credential_file"
  else
    : >"$github_credential_file"
  fi
  chmod 0600 "$github_credential_file"
}

prepare_git_credentials

# Docker Desktop forwards host.docker.internal to host loopback. Native Linux
# Docker resolves the same stable name through host-gateway, so Nexus must also
# listen on the host bridge rather than loopback only.
if [ "$(uname -s)" = "Linux" ]; then
  DEPENDENCY_PROXY_BIND_HOST=${DEPENDENCY_PROXY_BIND_HOST:-0.0.0.0}
  DEPENDENCY_GIT_MIRROR_BIND_HOST=${DEPENDENCY_GIT_MIRROR_BIND_HOST:-0.0.0.0}
else
  DEPENDENCY_PROXY_BIND_HOST=${DEPENDENCY_PROXY_BIND_HOST:-127.0.0.1}
  DEPENDENCY_GIT_MIRROR_BIND_HOST=${DEPENDENCY_GIT_MIRROR_BIND_HOST:-127.0.0.1}
fi
export DEPENDENCY_PROXY_BIND_HOST
export DEPENDENCY_GIT_MIRROR_BIND_HOST

compose() {
  docker compose -f "$compose_file" "$@"
}

wait_ready() {
  attempts=0
  until curl --fail --silent --output /dev/null "$nexus_url/service/rest/v1/status"; do
    attempts=$((attempts + 1))
    if [ "$attempts" -ge 120 ]; then
      echo "[dependency-cache] Nexus did not become ready at $nexus_url" >&2
      compose logs --tail 100 nexus >&2 || true
      exit 1
    fi
    sleep 2
  done
  attempts=0
  until curl --fail --silent --output /dev/null "$git_mirror_health_url"; do
    attempts=$((attempts + 1))
    if [ "$attempts" -ge 60 ]; then
      echo "[dependency-cache] Git mirror did not become ready at $git_mirror_url" >&2
      compose logs --tail 100 git-mirror >&2 || true
      exit 1
    fi
    sleep 1
  done
}

wait_git_mirror() {
  attempts=0
  until curl --fail --silent --output /dev/null "$git_mirror_health_url"; do
    attempts=$((attempts + 1))
    if [ "$attempts" -ge 60 ]; then
      echo "[dependency-cache] Git mirror did not become ready at $git_mirror_url" >&2
      compose logs --tail 100 git-mirror >&2 || true
      exit 1
    fi
    sleep 1
  done
