refresh_git_mirrors() {
  shift
  compose up -d --build git-mirror
  wait_git_mirror
  if [ "$#" -gt 0 ]; then
    payload=$(printf '%s\n' "$@")
    curl --fail --show-error --silent \
      --retry 8 --retry-delay 2 --retry-max-time 180 --retry-all-errors \
      --request POST \
      --data-binary "$payload" \
      "$git_mirror_url/cgi-bin/git/__servicegen_refresh"
